function report = solve_solid_of_revolution_disk(profile_sym, x_bounds, material_density)
% SOLVE_SOLID_OF_REVOLUTION_DISK Calculates the volume, mass, and axial moment
% of inertia for a solid of revolution generated by revolving y = f(x) around x-axis.
% Formulas:
%   Volume            : V = pi * \int_{x1}^{x2} [f(x)]^2 dx
%   Mass              : M = rho * V
%   Moment of Inertia : J_xx = 0.5 * pi * rho * \int_{x1}^{x2} [f(x)]^4 dx
%
% Syntax:
%   report = solve_solid_of_revolution_disk(profile_sym, x_bounds, material_density)
%
% Inputs:
%   profile_sym      - Symbolic expression y = f(x) (default: sqrt(9 - x^2) for radius a=3)
%   x_bounds         - Two-element limits vector [x1, x2] (default: [-3.0, 3.0])
%   material_density - Uniform material density rho in kg/m^3 (default = 1000.0)
%
% Outputs:
%   report           - Struct containing symbolic integral, volume, mass, and inertia

arguments
    profile_sym      = []
    x_bounds         (1,2) double = [-3.0, 3.0]
    material_density (1,1) double {mustBePositive} = 1000.0
end

syms x real
if isempty(profile_sym), profile_sym = sqrt(9 - x^2); end

x1 = x_bounds(1);
x2 = x_bounds(2);

if x1 >= x2
    error('Lower limit x1 must be strictly less than upper limit x2.');
end

% 1. Volume integral: V = pi * \int (y^2) dx
integrand_V_sym = simplify(pi * (profile_sym^2));
V_analytic_sym = int(integrand_V_sym, x, x1, x2);
volume_val = double(V_analytic_sym);

% 2. Mass calculation: M = rho * V
total_mass = material_density * volume_val;

% 3. Axial Moment of Inertia (J_xx) for disks: dJ_xx = 0.5 * r^2 dm = 0.5 * pi * rho * y^4 dx
integrand_J_sym = simplify(0.5 * pi * material_density * (profile_sym^4));
Jxx_analytic_sym = int(integrand_J_sym, x, x1, x2);
inertia_val = double(Jxx_analytic_sym);

% 4. Numerical validation via adaptive quadrature
handle_y = matlabFunction(profile_sym);
handle_vol = @(xv) pi * (handle_y(xv).^2);
vol_numerical = integral(handle_vol, x1, x2, 'RelTol', 1e-12, 'AbsTol', 1e-14);

discrepancy = abs(volume_val - vol_numerical);

% Assemble structured report
report.profile_function = char(profile_sym);
report.rotation_bounds = [x1, x2];
report.material_density = material_density;
report.symbolic_volume_integral = char(integrand_V_sym);
report.volume_cubic_units = volume_val;
report.total_mass_kg = total_mass;
report.axial_moment_of_inertia_Jxx = inertia_val;
report.numerical_volume_quadrature = vol_numerical;
report.discrepancy = discrepancy;

% Console report
fprintf('=== Solid of Revolution: Disk Method & Inertial Properties ===\n');
fprintf('Revolving Profile y = f(x) : %s\n', report.profile_function);
fprintf('Integration Axis Domain    : [%.4f, %.4f]\n', x1, x2);
fprintf('Uniform Density (rho)      : %.2f kg/m^3\n', material_density);
fprintf('Analytic Volume (V)        : %.10f cubic units\n', volume_val);
fprintf('Numerical Volume Check     : %.10f (Diff: %.2e)\n', vol_numerical, discrepancy);
fprintf('Total Rigid Body Mass (M)  : %.6f kg\n', total_mass);
fprintf('Axial Moment of Inertia Jxx: %.6f kg*m^2\n', inertia_val);
end